<!doctype html><html><head><meta charset="utf-8"><title>{{ $policy->policy_no }}</title><style>body{font-family:Arial,sans-serif;font-size:13px}.box{border:1px solid #333;padding:15px}.title{text-align:center}</style></head><body onload="window.print()"><div class="box"><h2 class="title">Insurance Policy Certificate</h2><p><b>Policy No:</b> {{ $policy->policy_no }}</p><p><b>Customer:</b> {{ $policy->customer_name }}</p><p><b>Mobile:</b> {{ $policy->mobile }}</p><p><b>NIC:</b> {{ $policy->nic_no }}</p><p><b>Sum Assured:</b> {{ number_format($policy->sum_assured,4) }}</p><p><b>Premium:</b> {{ number_format($policy->premium_amount,4) }}</p><p><b>Status:</b> {{ ucfirst($policy->status) }}</p></div></body></html>
